// Live leaderboard from Supabase (get_study_leaderboard) — NOT generated by Figma Make.
// Reuses the Figma leaderboard classes so it matches the friends page.
import type { LeaderboardRow } from "../lib/db";
import "./Supabase.css";

const COLORS = ["#e35345", "#577b50", "#4d6892", "#c3863c", "#b94d74"];

export default function CommunityLeaderboard({ rows, youId }: { rows: LeaderboardRow[]; youId?: string }) {
  const leading = Math.max(...rows.map((row) => Number(row.total_hours)), 1);
  return (
    <section className="leaderboard-section community-leaderboard">
      <div className="section-title">
        <div>
          <p className="kicker">EVERYONE ON STUDY HOPPER</p>
          <h2>Community leaderboard</h2>
        </div>
        <span className="week-label">all time</span>
      </div>
      {rows.length ? (
        <div className="leaderboard-list">
          {rows.map((row, index) => {
            const hours = Number(row.total_hours);
            return (
              <div key={row.user_id} className={`leaderboard-row ${row.user_id === youId ? "is-you" : ""}`}>
                <span className="leaderboard-rank">{row.rank}</span>
                <span
                  className="community-avatar"
                  style={{ background: COLORS[index % COLORS.length] }}
                  aria-hidden="true"
                >
                  {(row.display_name || "S").slice(0, 1).toUpperCase()}
                </span>
                <span className="leaderboard-progress">
                  <span>
                    <b>{row.user_id === youId ? `${row.display_name} (you)` : row.display_name}</b>
                    <strong>{hours.toFixed(hours % 1 ? 1 : 0)}h</strong>
                  </span>
                  <i><em style={{ width: `${Math.max(9, (hours / leading) * 100)}%` }} /></i>
                </span>
              </div>
            );
          })}
        </div>
      ) : (
        <p className="leaderboard-note">No sessions logged yet. Be the first to hop on!</p>
      )}
    </section>
  );
}
